"""Illustrative webhook flow; this is data, never run by VIVA."""
def accept_event(event, queue):
    if not event.get('id'):
        raise ValueError('event id required')
    queue.enqueue(event)

def deliver(event, client, store):
    result = client.post(event['url'], event['body'])
    store.record(event['id'], result.status_code)
    return result.status_code
